// expect: exit 11
// screen: 0 HELLO WORLD
// screen: 1 KHOOR ZRUOG
char msg[] = "HELLO WORLD";
char out[16];
int main(void)
{
    int i, k;
    cls();
    for (i = 0; msg[i]; i++) {
        k = msg[i];
        if (k >= 'A' && k <= 'Z')
            k = (k - 'A' + 3) % 26 + 'A';
        out[i] = k;
    }
    out[i] = 0;
    puts(msg);
    puts(out);
    return i;
}
